insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000000d', 'en', null, 'Art History', 'A guided survey of how humans have made and used images across time and cultures — from cave walls and pyramids to global modern movements — built around the skill of looking closely. Structure adapted from OpenStax Art History (CC BY 4.0).', null, 'foundations', 13, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000000d', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In visual analysis, the term ''composition'' refers to…","options":["the price of an artwork","how the parts are arranged within the frame","the artist''s biography","the type of paint used"],"answer":1,"explanation":"Composition is the arrangement of visual elements — see ''How to look at art''."},{"prompt":"The Great Pyramids at Giza were built by which ancient civilization?","options":["Ancient Greece","Ancient Egypt","Ancient Rome","The Maya"],"answer":1,"explanation":"Giza is Old Kingdom Egypt — see ''Ancient art''."},{"prompt":"Classical Greek sculpture is best known for pursuing…","options":["flat, symbolic figures","idealized, balanced human bodies","abstract geometric shapes","photographic realism of old age"],"answer":1,"explanation":"The Greek ideal balanced naturalism and perfected proportion — see ''Ancient art''."},{"prompt":"Medieval European cathedral windows made of coloured glass are called…","options":["frescoes","mosaics","stained glass","icons"],"answer":2,"explanation":"Stained glass filled Gothic cathedrals with coloured light — see ''Medieval and Renaissance art''."},{"prompt":"Renaissance artists used linear perspective mainly to…","options":["create the illusion of depth on a flat surface","avoid painting people","make colours brighter","speed up their work"],"answer":0,"explanation":"Perspective built believable three-dimensional space — see ''Medieval and Renaissance art''."},{"prompt":"Islamic art often favours geometric pattern and calligraphy because…","options":["artists could not draw","figural imagery was frequently avoided in religious contexts","colour was forbidden","paper did not exist"],"answer":1,"explanation":"Non-figural ornament flourished in many Islamic settings — see ''Global traditions''."},{"prompt":"The Benin Bronzes of West Africa were primarily made by…","options":["carving marble","lost-wax metal casting","weaving","oil painting"],"answer":1,"explanation":"Benin''s guilds cast brass and bronze by the lost-wax method — see ''Global traditions''."},{"prompt":"Impressionist painters such as Monet are known for capturing…","options":["exact historical detail","fleeting effects of light and atmosphere","religious icons only","black-and-white photographs"],"answer":1,"explanation":"Impressionism chased changing light and quick perception — see ''Modern and contemporary art''."}]}'::jsonb, null, 10),
  (2, 'How to look at art: elements and principles', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the basic visual elements and principles of design, and use them to describe any artwork. Warm-up: from the diagnostic, what one word means ''how the parts are arranged in the frame''?"},{"heading":"The idea","text":"Looking at art is a skill, not a talent. Start with the *elements* — the raw ingredients an artist works with: *line*, *shape*, *form*, *colour*, *value* (lightness/darkness), *texture*, and *space*. Then look at the *principles* — how those ingredients are organized: *balance* (symmetrical or asymmetrical), *emphasis* (what pulls your eye first, called the focal point), *rhythm* and *pattern* (repetition), *proportion* (relative size), and *unity*. Imagine a painting of a single red poppy against a grey field: the element is *colour*, and the principle is *emphasis* — the lone warm red becomes the focal point in a cool, quiet space."},{"heading":"Worked example","text":"Describe a portrait in which a figure stands off to the left, lit from a window on the right, wearing a bright blue robe against a dark brown wall. Elements: strong *value* contrast (light face, dark background), saturated *colour* (blue robe). Principles: *asymmetrical balance* (the off-centre figure is balanced by the bright window light), and *emphasis* on the illuminated face. Notice we described what we *see* before saying whether we like it — analysis comes before judgment."},{"heading":"Your turn","text":"Name the element or principle at work: (1) a long diagonal edge that leads your eye across the canvas, (2) a checkerboard of repeated squares, (3) a giant figure next to tiny background people, (4) a face lit brightly against deep shadow, (5) a composition that reads the same on the left and right. Answers: (1) line, (2) pattern/rhythm, (3) proportion (hierarchy of scale), (4) value contrast / emphasis, (5) symmetrical balance."},{"heading":"Common mistakes & exit ticket","text":"Mistake: jumping straight to ''I like it'' — description must come first. Mistake: confusing *value* (light vs. dark) with *colour* (hue). Exit: (a) Is ''balance'' an element or a principle? (b) What do we call the spot the eye goes first? Answers: a principle; the focal point (emphasis)."}]}'::jsonb, 'Two toolkits: elements are the ingredients (line, shape, colour…); principles are how you arrange them (balance, rhythm, emphasis…).', 12),
  (3, 'Ancient art: Egypt, Greece, and Rome', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish Egyptian, Greek, and Roman art by their aims and looks. Warm-up: which civilization built the pyramids at Giza?"},{"heading":"The idea","text":"*Ancient Egyptian* art served eternity and the state. Figures follow a *canon of proportions* and a *composite view* — head and legs in profile, eye and shoulders frontal — not because artists ''couldn''t'' foreshorten, but because clarity and permanence mattered more than a single viewpoint. *Ancient Greek* art pursued an *ideal*: sculptors like Polykleitos worked out proportions for a perfectly balanced body, combining lifelike observation with mathematical harmony (*contrapposto*, the relaxed weight-shift stance, dates from this moment). *Ancient Roman* art borrowed Greek ideals but added sharp *veristic* portraiture (wrinkles, receding hairlines — signs of experience) and vast engineering: the *arch*, *concrete*, and buildings like the Pantheon with its coffered dome and central oculus."},{"heading":"Worked example","text":"Compare two standing male figures. The Egyptian one is rigid, one foot forward, arms locked at the sides, gaze fixed forward — an image of enduring order. The Greek one shifts its weight onto one leg so the hips and shoulders tilt in opposite directions (contrapposto), suggesting a body that could breathe and move. Same subject, opposite values: eternal stillness versus living ideal."},{"heading":"Your turn","text":"Match the trait to the culture: (1) composite ''profile-and-frontal'' figures, (2) contrapposto and idealized bodies, (3) blunt, wrinkled portrait busts, (4) concrete domes and triumphal arches, (5) a canon built for permanence and the afterlife. Choices: Egypt / Greece / Rome. Answers: (1) Egypt, (2) Greece, (3) Rome, (4) Rome, (5) Egypt."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking Egyptian ''flatness'' means lack of skill — it was a deliberate visual language. Mistake: assuming Rome merely copied Greece (it innovated in realism and engineering). Exit: (a) What stance shows a natural weight-shift? (b) Which culture is famous for veristic, aged portrait busts? Answers: contrapposto; Rome."}]}'::jsonb, 'A rough arc: Egyptian order and permanence → Greek idealized naturalism → Roman realism and engineering.', 13),
  (4, 'From cathedrals to the Renaissance', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how medieval religious art and Renaissance art differ in goals and techniques. Warm-up: what do we call the coloured-glass windows of a Gothic cathedral?"},{"heading":"The idea","text":"*Medieval* European art was overwhelmingly religious and symbolic. Byzantine *icons* and *mosaics* used flat, frontal figures and shimmering gold grounds to signal the sacred and timeless, not a physical place. *Gothic* cathedrals — with pointed arches, ribbed vaults, flying buttresses, and vast *stained-glass* windows — turned stone into cages of coloured light meant to lift the mind toward heaven. The *Renaissance* (''rebirth''), beginning in 14th–15th-century Italy, shifted attention back to the observable world and to classical antiquity. Artists developed *linear perspective* (a geometric system for depth, credited to Brunelleschi and codified by Alberti), studied *anatomy*, and modelled form with *chiaroscuro* (light-and-shadow). Figures gained weight, individuality, and believable space."},{"heading":"Worked example","text":"Set a gold-ground medieval Madonna beside a Renaissance one. In the medieval image, Mary floats frontally on flat gold, her size larger than surrounding figures to show her importance (*hierarchy of scale*), space is symbolic. In the Renaissance image, she sits in a measurable room whose tiled floor recedes to a single *vanishing point*, light falls consistently from one side, and her body has convincing volume. The subject is unchanged; the pictorial logic moved from symbol to observation."},{"heading":"Your turn","text":"Medieval or Renaissance? (1) flat gold background with frontal saints, (2) a tiled floor receding to one vanishing point, (3) figure size set by spiritual importance, (4) careful anatomical modelling in light and shadow, (5) stained glass and pointed arches. Answers: (1) medieval, (2) Renaissance, (3) medieval, (4) Renaissance, (5) medieval (Gothic)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling medieval art ''primitive'' — its abstraction was purposeful theology, not failure. Mistake: thinking perspective is just ''more realistic'' rather than a specific geometric system. Exit: (a) What system creates measured depth toward a vanishing point? (b) What does chiaroscuro model? Answers: linear perspective; form through light and shadow."}]}'::jsonb, 'Medieval art points beyond the world (symbol, gold, light); Renaissance art reclaims this world (perspective, anatomy, observation).', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The ''principle'' that decides which part of an artwork your eye reaches first is…","options":["texture","emphasis","hue","line"],"answer":1,"explanation":"Emphasis creates the focal point."},{"prompt":"A figure standing with its weight shifted onto one leg, hips and shoulders tilting, shows…","options":["the composite view","contrapposto","chiaroscuro","hierarchy of scale"],"answer":1,"explanation":"Contrapposto is the Greek weight-shift stance."},{"prompt":"Egyptian figures combining a profile head with a frontal eye and shoulders use the…","options":["vanishing point","composite view","veristic style","golden ratio"],"answer":1,"explanation":"The composite view prized clarity of each part."},{"prompt":"Which is a hallmark of Gothic cathedrals?","options":["concrete domes","flying buttresses and stained glass","gold-ground icons","contrapposto statues"],"answer":1,"explanation":"Gothic structure enabled tall walls of coloured glass."},{"prompt":"Linear perspective is best described as…","options":["a type of paint","a geometric system for depicting depth","a Roman building material","an Egyptian proportion canon"],"answer":1,"explanation":"Lines converge to a vanishing point to imply space."},{"prompt":"Making an important figure larger than others regardless of real space is called…","options":["chiaroscuro","hierarchy of scale","contrapposto","impasto"],"answer":1,"explanation":"Size signals importance, common in medieval art."}]}'::jsonb, null, 8),
  (6, 'Global traditions: Asia, Africa, the Islamic world, and the Americas', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe distinctive aims of several non-Western traditions and resist judging them by European standards. Warm-up: why does much Islamic religious art favour pattern and calligraphy over figures?"},{"heading":"The idea","text":"Great art was made everywhere, on its own terms. In *East Asia*, Chinese *literati* ink painting valued the expressive trace of the brush and often left large areas of empty paper as active *negative space* suggesting mist or void; Japanese woodblock prints (*ukiyo-e*) used flat colour, bold outline, and asymmetry. In the *Islamic world*, where figural imagery was often avoided in sacred contexts, artists perfected *geometric arabesque*, *vegetal ornament*, and exquisite *calligraphy*, covering mosques and manuscripts with infinite, non-representational pattern. Across *Africa*, the Kingdom of Benin cast intricate brass plaques and heads by the *lost-wax* method, while masks and figures elsewhere served ritual and community rather than gallery display. In the *Americas*, Indigenous peoples — Maya, Aztec, Inka, and North American nations — built pyramids and cities, carved stone stelae, wove textiles, and made ceramics carrying dense symbolic meaning."},{"heading":"Worked example","text":"Look at a Chinese hanging scroll of a tiny fisherman below towering, mist-wrapped mountains. Nearly half the surface is bare paper. By European ''fill-the-frame'' habits this might seem ''unfinished'' — but the emptiness *is* the subject: it evokes vastness and the smallness of humanity within nature. Now picture a mosque wall of interlocking star-and-polygon tilework: it has no focal figure at all, because its endless, repeating geometry is meant to suggest the infinite. Two very different definitions of a finished, meaningful image."},{"heading":"Your turn","text":"Match the tradition to the trait: (1) lost-wax cast brass heads and plaques, (2) ink landscapes using empty space as mist, (3) geometric arabesque and calligraphy instead of figures, (4) flat-colour woodblock prints of everyday life, (5) stone pyramids, stelae, and symbolic textiles. Choices: West Africa (Benin) / China / Islamic world / Japan / Indigenous Americas. Answers: (1) Benin, (2) China, (3) Islamic world, (4) Japan, (5) Indigenous Americas."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating European naturalism as the yardstick for all art — each tradition sets its own goals. Mistake: calling empty space in ink painting ''unfinished'' when it is deliberate and meaningful. Exit: (a) Name the metal-casting method used at Benin. (b) In much Islamic sacred art, what replaces figural imagery? Answers: lost-wax casting; geometric pattern and calligraphy."}]}'::jsonb, 'Art history is global: ''masterpiece'' looks different in ink, brass, tile, and clay. Judge each tradition by its own aims.', 14),
  (7, 'Modern and contemporary art: Impressionism to today', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace the move from Impressionism toward abstraction and conceptual art, and name a few key movements. Warm-up: what did Impressionists most want to capture?"},{"heading":"The idea","text":"From the 1860s, artists broke from academic tradition. *Impressionism* (Monet, Morisot) used loose, visible brushstrokes and bright colour to capture fleeting *light* and a passing moment. *Post-Impressionism* (Cézanne, Van Gogh) pushed further into structure and emotion. Then the leap to *abstraction*: *Cubism* (Picasso, Braque) shattered objects into multiple simultaneous viewpoints; *Expressionism* prioritized inner feeling; artists like Kandinsky removed recognizable subjects altogether. Mid-century *Abstract Expressionism* made the physical act of painting the subject. Later, *Pop Art* (Warhol) borrowed advertising and mass media, and *Conceptual art* argued that the *idea* could matter more than the crafted object. Contemporary art today is global and pluralistic — installation, video, performance, and identity-driven work sit alongside painting."},{"heading":"Worked example","text":"Imagine a single haystack painted many times by the same artist at dawn, noon, and dusk. The stack barely changes, but the colours swing from cool blue-violet to blazing orange — the true subject is *light and time*, not the hay (Impressionism). Now picture a portrait where a face is split into fractured planes so you seem to see the front and side at once (Cubism), and finally a giant canvas of dripped and flung paint with no subject at all, recording only the artist''s movement (Abstract Expressionism). Three steps away from ''a window onto the world.''"},{"heading":"Your turn","text":"Name the movement: (1) loose brushwork chasing changing daylight, (2) an object shown from several viewpoints at once in fractured planes, (3) soup-can and celebrity imagery from mass media, (4) dripped paint recording the artist''s gesture, (5) art where the concept outranks the physical object. Answers: (1) Impressionism, (2) Cubism, (3) Pop Art, (4) Abstract Expressionism, (5) Conceptual art."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking abstract art means ''no skill'' — it is a deliberate choice about what a picture is for. Mistake: assuming modern art is only Western; it has always been global and grows more so. Exit: (a) Which movement fractured objects into multiple viewpoints? (b) What did Impressionists most want to record? Answers: Cubism; fleeting light and the moment."}]}'::jsonb, 'Modern art''s arc: from painting what you see → what you feel → what paint itself is → what an idea can be.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"composition","translation":"the arrangement of visual elements within the frame of an artwork","example":"The diagonal composition leads your eye from corner to corner."},{"term":"contrapposto","translation":"a standing pose with the body''s weight shifted onto one leg so the hips and shoulders tilt","example":"Greek sculptors used contrapposto to make marble figures feel alive."},{"term":"linear perspective","translation":"a geometric system that creates the illusion of depth by having lines converge at a vanishing point","example":"Renaissance painters used linear perspective to build convincing rooms."},{"term":"chiaroscuro","translation":"the modelling of form through strong contrasts of light and shadow","example":"Chiaroscuro gives the face a rounded, three-dimensional look."},{"term":"arabesque","translation":"flowing, interlaced geometric and plant-based ornament common in Islamic art","example":"The mosque wall was covered in tile arabesque with no figures at all."},{"term":"abstraction","translation":"art that departs from realistic depiction, emphasizing shape, colour, or idea over likeness","example":"Kandinsky pushed abstraction until no object remained on the canvas."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Large areas of empty paper in a Chinese ink landscape are best understood as…","options":["an unfinished mistake","meaningful negative space suggesting mist or void","a lack of ink","a printing error"],"answer":1,"explanation":"Emptiness is a deliberate, expressive element."},{"prompt":"The Benin heads and plaques of West Africa were made by…","options":["oil painting","lost-wax metal casting","weaving","stained glass"],"answer":1,"explanation":"Benin guilds cast brass and bronze by the lost-wax method."},{"prompt":"Impressionism is best characterized by its interest in…","options":["exact anatomical detail","fleeting light and momentary perception","gold-ground icons","geometric arabesque"],"answer":1,"explanation":"Impressionists chased changing light and atmosphere."},{"prompt":"Cubism is known for…","options":["photographic realism","showing objects from multiple viewpoints in fractured planes","religious mosaics","veristic portrait busts"],"answer":1,"explanation":"Cubism broke the single viewpoint apart."},{"prompt":"In much Islamic religious art, figural images are often replaced by…","options":["portrait busts","geometric pattern and calligraphy","linear perspective","contrapposto figures"],"answer":1,"explanation":"Non-figural ornament flourished in sacred settings."},{"prompt":"Conceptual art argues that the most important part of an artwork is…","options":["its price","the idea behind it","the size of the canvas","the frame"],"answer":1,"explanation":"The concept can outrank the crafted object."}]}'::jsonb, null, 8),
  (10, 'Applied project: a visual analysis of an artwork you choose', 'writing', '{"sections":[{"heading":"The task","text":"Choose any single artwork you can look at closely — a painting, sculpture, print, textile, building, or object, from any culture or period. Write a short *visual analysis* (roughly 250–400 words) that describes what you see and how it works, using the vocabulary from this course. You are not researching the artist''s biography; you are training your own eye."},{"heading":"Milestones","text":"1) Identify the work (title, maker or culture, and rough date if known). 2) Describe the *elements* you notice: line, shape, colour, value, texture, and use of space. 3) Analyze the *principles*: where is the focal point (emphasis)? Is the balance symmetrical or asymmetrical? Is there rhythm or hierarchy of scale? 4) Locate it in a tradition covered in this course (e.g. ancient, medieval, Renaissance, a global tradition, or a modern movement) and say why. 5) Only at the end, offer an interpretation: what feeling or meaning does the arrangement create?"},{"heading":"Self-check rubric","text":"✔ You described before you judged — analysis precedes opinion. ✔ You used at least four course terms correctly (e.g. composition, contrapposto, chiaroscuro, negative space, emphasis, abstraction). ✔ You named a specific focal point and the kind of balance. ✔ You connected the work to a period or tradition with a reason. ✔ Your interpretation grows out of what you actually observed, not outside facts. If all five are true, you are analyzing like an art historian."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000000d' and l.position = v.pos
);
